#pragma once

#include "mpreal.h"
#include "nlohmann/json.hpp"

namespace Core {

/**
 * @brief Represents a trading signal generated by strategies/algorithms
 *
 * Signals are used by the trading engine to make position decisions.
 * A positive signal_strength indicates a position (can be long or short), while
 * a negative value suggests that it should be closed if it exists. The
 * magnitude represents the confidence level of the signal.
 */

struct Signal {
    mpfr::mpreal signal_strength;  // Trading signal strength (-1.0 to 1.0)
    float prediction;  // Optional price prediction for custom strategy logic
    double price;      // Price at which the signal was generated
    long long event_time_ms;      // Millisecond timestamp set by the engine
    long long bar_close_time_ms;  // Millisecond timestamp of the bar close
    std::unordered_map<std::string, double> kv_cache = {};
    unsigned long long signal_id = 0;
    long long strategy_id = 0;
    std::string symbol;

    nlohmann::json to_json() const;
    static Signal from_json(const nlohmann::json& json);

    bool operator==(const Signal& other) const {
        return signal_strength == other.signal_strength &&
               prediction == other.prediction && price == other.price &&
               event_time_ms == other.event_time_ms &&
               bar_close_time_ms == other.bar_close_time_ms &&
               signal_id == other.signal_id;
    }

    bool operator!=(const Signal& other) const { return !(*this == other); }
};

}  // namespace Core
